  if(b.t==='q') return '<blockquote class="mg-q"><p>'+esc(b.q)+'</p><cite>'+esc(b.r)+'</cite></blockquote>';
  if(b.t==='ul') return '<ul class="mg-ul">'+b.items.map(function(i){return '<li>'+esc(plain(i))+'</li>'}).join('')+'</ul>';
  if(b.t==='sig') return '<div class="mg-sig">'+esc(b.h)+'</div>';
  if(b.t==='sec') return '<section class="mg-sec'+(b.theme?' th':'')+'"><div class="mg-tag">'+esc(b.n)+'</div>'+b.c.map(htmlBlock).join('')+'</section>';
