  if(crat(cur,bg)<tgt||crat(cur,qbg)<tgt){ var ok=false; for(var t=0.05;t<=1.001;t+=0.05){ var c=mixC(ac,ink,t); if(crat(c,bg)>=tgt&&crat(c,qbg)>=tgt){cur=c;ok=true;break} } if(!ok) cur=ink; }
